// Original saturated worlds, with five mode-specific courses and independent selections per game.
const VIVID_WORLDS=[
{floor:'#149768',light:'#54d273',path:'#e8d17e',edge:'#173c51',stone:'#548bad',top:'#b8e1ee',bush:'#076956',leaf:'#32bd79',accent:'#fff04d',water:'#137fc4'},
{floor:'#e97b2c',light:'#ffb543',path:'#ffe28a',edge:'#50304f',stone:'#bd5877',top:'#ffc0a2',bush:'#197d69',leaf:'#4fce81',accent:'#fff253',water:'#218dca'},
{floor:'#3056c7',light:'#69acff',path:'#99c6f7',edge:'#142755',stone:'#526ed0',top:'#bbd8ff',bush:'#35449c',leaf:'#7e9fff',accent:'#ffe940',water:'#22bacc'},
{floor:'#068f9f',light:'#41ddc8',path:'#ffe49a',edge:'#073c63',stone:'#358ec4',top:'#b9f4ef',bush:'#166e7c',leaf:'#3adbad',accent:'#ffdd48',water:'#2466ce'},
{floor:'#713acb',light:'#bb79ff',path:'#e6bbff',edge:'#281856',stone:'#6867d4',top:'#d7d4ff',bush:'#3f398f',leaf:'#7c83ff',accent:'#50ffce',water:'#3569cb'}
];
MAPS.forEach((map,i)=>Object.assign(map,VIVID_WORLDS[i]));
const COURSE_SETS={
arena:[['Scholar Showdown','Garden lanes with flanking cover'],['Ember Outpost','Offset walls and tight approaches'],['Moonlight Foundry','Staggered cover and long firing lanes'],['Coral Crossing','Twin crossings with exposed centre lanes'],['Neon Stronghold','Fortress corners and pressure zones']],
rally:[['Sunburst Circuit','Wide bends · balanced overtaking'],['Canyon Switchbacks','Sharper turns · narrow checkpoints'],['Moonlight Speedway','Fast sweeps · drifting rivals'],['Tidal Causeway','Flowing chicanes · crystal lines'],['Neon Grand Prix','Tight slalom · close overtaking']],
leap:[['Canopy Skyway','Stepped islands · steady jumps'],['Ember Ascent','Higher climbs · smaller landings'],['Moonbeam Bridges','Moving islands · rhythm jumps'],['Coral Cloud Isles','Wide gaps · floating relic routes'],['Neon Rooftops','Compact platforms · drone patrols']],
tower:[['Garden Bastion','Two long bends · balanced build pads'],['Canyon Gate','A winding route with close corners'],['Moonlight Junction','Central turns · overlapping tower ranges'],['Coral Rampart','A coastal zigzag · exposed last stretch'],['Neon Citadel','An extended route with sharp turns']],
dodge:[['Meteor Gardens','Warning rings and falling meteors'],['Ember Storm','Diagonal showers and ring clusters'],['Moonlight Surge','Crossing projectiles and sweep warnings'],['Coral Tempest','Alternating sweeps and star routes'],['Neon Eclipse','Mixed patterns and shorter safe windows']],
maze:[['Garden Labyrinth','Long corridors · roaming guardian'],['Canyon Catacombs','Tighter turns · scattered relics'],['Moonlit Ruins','Dense passages · deep vaults'],['Tidal Archives','Twisting routes · distant relics'],['Neon Lockworks','Complex paths · relentless pursuit']],
space:[['Cloud Orbit','Mixed drone formations'],['Solar Belt','Armoured escorts and crossfire'],['Lunar Patrol','Swaying fleets and aimed volleys'],['Coral Nebula','Wide formations and surprise angles'],['Neon Frontier','Tight waves and guardian pressure']],
memory:[['Glyph Garden','Classic symbol vault'],['Sunstone Archive','Extra pairs and warm symbols'],['Moonlit Library','Cool colours and precise recall'],['Tide Echo Vault','Wider grid and longer combinations'],['Neon Code Vault','More pairs and demanding recall']]
};
function courseMode(){return live?'arena':selectedGame().id}
function selectedCourse(mode=courseMode()){const saved=profile.courseChoices?.[mode]||profile.battlefield||'springs';return MAPS.some(m=>m.id===saved)?saved:'springs'}
function courseMap(mode=courseMode(),id=selectedCourse(mode)){const i=Math.max(0,MAPS.findIndex(m=>m.id===id)),definition=(COURSE_SETS[mode]||COURSE_SETS.arena)[i];return{...MAPS[i],name:definition[0],courseNote:definition[1],baseIndex:i,courseMode:mode,curve:[.85,1.35,1.1,1.5,1.65][i],lanePenalty:[0,14,5,10,18][i],extraPairs:[0,1,0,2,2][i]}}
selectedMap=function(){return courseMap(courseMode(),live?.config?.map||selectedCourse(courseMode()))};
function chooseCourse(mode,id){if(live){toast('Leave the room before selecting another course.');return}if(!COURSE_SETS[mode]||!MAPS.some(m=>m.id===id))return;profile.courseChoices??={};profile.courseChoices[mode]=id;profile.battlefield=id;save()}
battlefieldCards=function(){const mode=selectedGame().id,noun={arena:'arena',rally:'racecourse',leap:'island route',tower:'defence map',dodge:'storm zone',maze:'labyrinth',space:'flight sector',memory:'vault'}[mode];return `<section class="battlefield-picker"><div class="section-title"><div><h2>Choose your ${noun}.</h2><p>Five locations made for ${selectedGame().name}. Preview the layout and challenge before choosing.</p></div><span class="count">${FIELD_TIER_NAMES[fieldTier()-1].toUpperCase()}</span></div><div class="course-grid">${MAPS.map((m,i)=>{const course=courseMap(mode,m.id),active=selectedCourse(mode)===m.id;return `<article class="course-card ${active?'selected':''}" style="--map-accent:${course.accent}"><button class="game-preview-tile" data-preview-course="${mode}:${m.id}" aria-label="Preview ${course.name}"><canvas width="400" height="260" data-game-preview="${mode}" data-course-preview="${m.id}" aria-label="${course.name} course preview"></canvas><span class="preview-play-icon">▶ Course preview</span></button><h3>${course.name} ${active?'✓':''}</h3><p>${course.courseNote}</p><small class="course-music">♫ ${typeof BIOME_SCORES!=='undefined'?BIOME_SCORES[course.terrain]?.name||'Original score':'Original score'}</small><div class="game-card-options"><button class="preview-text" data-preview-course="${mode}:${m.id}">View course</button><button class="choose-game-btn" data-course="${mode}:${m.id}" aria-pressed="${active}">${active?'Selected ✓':'Choose'}</button></div></article>`}).join('')}</div></section>`};
function openCoursePreview(mode,id){const map=courseMap(mode,id),gameInfo=GAME_MODES.find(m=>m.id===mode);openModal(`${topModal('COURSE PREVIEW · '+gameInfo.tag)}<h2 id="modal-title">${map.name}</h2><p class="sub">${gameInfo.name} · ${map.courseNote}</p><p class="course-music">♫ ${typeof BIOME_SCORES!=='undefined'?BIOME_SCORES[map.terrain]?.name||'Original environment score':'Original environment score'}</p><div class="large-game-preview"><canvas width="800" height="520" data-game-preview="${mode}" data-course-preview="${id}" aria-label="Animated preview of ${map.name}"></canvas><span>ACTUAL GAME ART · COURSE LAYOUT DEMONSTRATION</span></div><div class="preview-instructions"><h3>Your challenge</h3><p>${gameInfo.help}</p><p>Higher player levels and cleared stages add tougher targets, obstacles and attack patterns.</p></div><div class="modal-actions"><button class="primary" data-course-start="${mode}:${id}">Choose course & warm up →</button><button class="secondary" data-action="close">Back to courses</button></div>`);queueGamePreviews()}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const preview=b.dataset.previewCourse,choice=b.dataset.course,start=b.dataset.courseStart;if(!preview&&!choice&&!start)return;event.preventDefault();event.stopImmediatePropagation();const[mode,id]=(preview||choice||start).split(':');if(preview){openCoursePreview(mode,id);return}profile.gameType=mode;chooseCourse(mode,id);closeModal();navigate('home');if(start)chooseBattleTopics();else{document.querySelector('[data-course="'+mode+':'+id+'"]')?.focus({preventScroll:true});toast(courseMap(mode,id).name+' selected.')}},true);
document.addEventListener('click',event=>{if(event.target.closest('button[data-game]')&&!live)document.querySelector('.battlefield-picker')?.scrollIntoView?.({behavior:'smooth',block:'start'})});
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
